/**
 * src/lib/supabase.ts
 * CampusShare – Supabase client initialisation.
 *
 * The `Database` type is generated by the Supabase CLI:
 *   npx supabase gen types typescript --local > src/lib/database.types.ts
 */

import { createClient, SupabaseClient } from '@supabase/supabase-js';
import type { Database } from './database.types';

// ---------------------------------------------------------------------------
// Environment validation
// ---------------------------------------------------------------------------
const _url  = import.meta.env.VITE_SUPABASE_URL  as string | undefined;
const _key  = import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined;

if (!_url)  throw new Error('[CampusShare] Missing env var: VITE_SUPABASE_URL');
if (!_key)  throw new Error('[CampusShare] Missing env var: VITE_SUPABASE_ANON_KEY');

const supabaseUrl     = _url;
const supabaseAnonKey = _key;

// ---------------------------------------------------------------------------
// Singleton client
// ---------------------------------------------------------------------------
export const supabase: SupabaseClient<Database> = createClient<Database>(
  supabaseUrl,
  supabaseAnonKey,
  {
    auth: {
      persistSession:    true,
      autoRefreshToken:  true,
      detectSessionInUrl: true,
    },
  }
);

// ---------------------------------------------------------------------------
// Error type
// ---------------------------------------------------------------------------

/** A structured error carrying the machine-readable code from the DB. */
export class CampusShareError extends Error {
  /** Stable machine code, e.g. 'not_verified', 'slot_taken', 'not_eligible:user_type_not_allowed' */
  readonly code: string;
  /** Optional detail after the first colon (e.g. qualification names, slot names). */
  readonly reason: string | undefined;

  constructor(code: string, reason?: string, originalMessage?: string) {
    super(originalMessage ?? [code, reason].filter(Boolean).join(': '));
    this.name   = 'CampusShareError';
    this.code   = code;
    this.reason = reason;
  }
}

// ---------------------------------------------------------------------------
// unwrap helper
// ---------------------------------------------------------------------------

/** Shape covering all Supabase JS response variations (tables, RPC, auth). */
interface SupabaseResponseLike<T> {
  data?: unknown;
  error: { message: string; code?: string } | null;
}

/**
 * Unwraps a Supabase response, throwing a `CampusShareError` on error.
 *
 * Postgres exceptions raised by our RPCs have the format:
 *   MESSAGE = '<code>' or '<code>:<detail>'
 *
 * supabase-js surfaces this in `error.message`.
 */
export function unwrap<T>(response: SupabaseResponseLike<T>): T {
  if (response.error !== null) {
    const raw        = response.error.message ?? '';
    const firstColon = raw.indexOf(':');
    const code       = firstColon === -1 ? raw.trim() : raw.slice(0, firstColon).trim();
    const reason     = firstColon === -1 ? undefined : raw.slice(firstColon + 1).trim() || undefined;
    throw new CampusShareError(code, reason, raw);
  }
  return response.data as T;
}

export default supabase;
